import { test, expect } from '@playwright/test';

test.describe('Video Player Responsive Tablet Viewport', () => {
  const TABLET_WIDTH = 768;
  const TABLET_HEIGHT = 1024;
  const MOBILE_WIDTH = 375;
  const MOBILE_HEIGHT = 667;
  const DESKTOP_WIDTH = 1920;
  const DESKTOP_HEIGHT = 1080;

  test.beforeEach(async ({ page }) => {
    // Set tablet viewport
    await page.setViewportSize({ width: TABLET_WIDTH, height: TABLET_HEIGHT });
    // Navigate to a page with video player
    await page.goto('about:blank');
    // Create a mock video player for testing
    await page.setContent(`
      <html>
        <head>
          <style>
            body {
              margin: 0;
              padding: 20px;
              background-color: #f0f0f0;
            }
            .video-container {
              width: 100%;
              max-width: 800px;
              aspect-ratio: 16 / 9;
              background-color: #000;
              margin: 0 auto;
            }
            video {
              width: 100%;
              height: 100%;
              object-fit: contain;
            }
          </style>
        </head>
        <body>
          <div class="video-container">
            <video controls>
              <source src="https://www.w3schools.com/html/mov_bbb.mp4" type="video/mp4">
              Your browser does not support the video tag.
            </video>
          </div>
        </body>
      </html>
    `);
  });

  test('should resize video player proportionally on tablet viewport', async ({ page }) => {
    // Get the video container
    const videoContainer = page.locator('.video-container');

    // Verify container exists
    await expect(videoContainer).toBeVisible();

    // Get the bounding box of the video container
    const containerBox = await videoContainer.boundingBox();

    // Verify container dimensions are appropriate for tablet
    expect(containerBox).not.toBeNull();
    expect(containerBox?.width).toBeLessThanOrEqual(TABLET_WIDTH - 40); // accounting for padding
    expect(containerBox?.height).toBeGreaterThan(0);

    // Verify aspect ratio is maintained (16:9)
    const aspectRatio = containerBox!.width / containerBox!.height;
    expect(aspectRatio).toBeCloseTo(16 / 9, 1);
  });

  test('should maintain aspect ratio when resizing from mobile to tablet', async ({ page }) => {
    // First, set mobile viewport
    await page.setViewportSize({ width: MOBILE_WIDTH, height: MOBILE_HEIGHT });

    const videoContainer = page.locator('.video-container');
    const mobileBox = await videoContainer.boundingBox();
    const mobileAspectRatio = mobileBox!.width / mobileBox!.height;

    // Now resize to tablet
    await page.setViewportSize({ width: TABLET_WIDTH, height: TABLET_HEIGHT });

    // Wait for any resize animations
    await page.waitForTimeout(500);

    const tabletBox = await videoContainer.boundingBox();
    const tabletAspectRatio = tabletBox!.width / tabletBox!.height;

    // Verify aspect ratio is maintained
    expect(tabletAspectRatio).toBeCloseTo(mobileAspectRatio, 1);
    expect(tabletAspectRatio).toBeCloseTo(16 / 9, 1);

    // Verify width increased
    expect(tabletBox!.width).toBeGreaterThan(mobileBox!.width);
  });

  test('should scale video player correctly across different tablet orientations', async ({ page }) => {
    // Portrait orientation (already set in beforeEach)
    const portraitContainer = page.locator('.video-container');
    const portraitBox = await portraitContainer.boundingBox();
    const portraitAspectRatio = portraitBox!.width / portraitBox!.height;

    // Verify portrait aspect ratio
    expect(portraitAspectRatio).toBeCloseTo(16 / 9, 1);

    // Switch to landscape orientation
    await page.setViewportSize({ width: TABLET_HEIGHT, height: TABLET_WIDTH });
    await page.waitForTimeout(500);

    const landscapeBox = await portraitContainer.boundingBox();
    const landscapeAspectRatio = landscapeBox!.width / landscapeBox!.height;

    // Verify landscape aspect ratio is maintained
    expect(landscapeAspectRatio).toBeCloseTo(16 / 9, 1);

    // Verify width increased in landscape
    expect(landscapeBox!.width).toBeGreaterThan(portraitBox!.width);
  });

  test('should not exceed max-width constraint on tablet', async ({ page }) => {
    const videoContainer = page.locator('.video-container');
    const containerBox = await videoContainer.boundingBox();

    // Verify max-width of 800px is respected
    expect(containerBox!.width).toBeLessThanOrEqual(800);
  });

  test('should center video player on tablet viewport', async ({ page }) => {
    const videoContainer = page.locator('.video-container');
    const containerBox = await videoContainer.boundingBox();

    // Get viewport size
    const viewportSize = page.viewportSize();

    // Calculate left and right margins
    const leftMargin = containerBox!.x;
    const rightMargin = viewportSize!.width - (containerBox!.x + containerBox!.width);

    // Verify container is centered (margins should be approximately equal)
    expect(Math.abs(leftMargin - rightMargin)).toBeLessThan(5);
  });

  test('should resize video player when viewport changes dynamically', async ({ page }) => {
    const videoContainer = page.locator('.video-container');

    // Get initial size at tablet viewport
    const initialBox = await videoContainer.boundingBox();
    const initialWidth = initialBox!.width;

    // Resize to a smaller tablet viewport
    await page.setViewportSize({ width: 600, height: 800 });
    await page.waitForTimeout(500);

    const smallerBox = await videoContainer.boundingBox();

    // Verify width decreased
    expect(smallerBox!.width).toBeLessThan(initialWidth);

    // Verify aspect ratio is still maintained
    const aspectRatio = smallerBox!.width / smallerBox!.height;
    expect(aspectRatio).toBeCloseTo(16 / 9, 1);

    // Resize back to original tablet size
    await page.setViewportSize({ width: TABLET_WIDTH, height: TABLET_HEIGHT });
    await page.waitForTimeout(500);

    const resizedBox = await videoContainer.boundingBox();

    // Verify width is back to original
    expect(resizedBox!.width).toBeCloseTo(initialWidth, 0);
  });
});
